def random_pokemon(seed=None, **_extra):
    import json, os, datetime, time, random, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0021000" if __import__("os").path.isdir("./environment_mix/0021000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    tool_name = "random-pokemon"
    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        if not isinstance(s, str):
            return None
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}_{secrets.token_hex(8)}"

    tool_requests = _load("tool_requests.json")
    created_at = _now_iso()

    # Rate/quota policy (observable dynamics): keep consistent with existing dataset (has 429/burst 30/10s).
    client_id = _extra.get("client_id") or "web:chat"
    burst_n = 30
    burst_window_s = 10
    daily_quota = 5000

    def _count_in_window(rows, window_s):
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)
        c = 0
        for r in rows:
            if r.get("tool_name") != tool_name:
                continue
            if (r.get("client_id") or "web:chat") != client_id:
                continue
            dt = _parse_iso(r.get("created_at"))
            if dt and dt >= cutoff:
                c += 1
        return c

    def _count_today(rows):
        today = datetime.datetime.utcnow().date()
        c = 0
        for r in rows:
            if r.get("tool_name") != tool_name:
                continue
            if (r.get("client_id") or "web:chat") != client_id:
                continue
            dt = _parse_iso(r.get("created_at"))
            if dt and dt.date() == today:
                c += 1
        return c

    req_row = {
        "tool_request_id": _new_id("trq"),
        "tool_name": tool_name,
        "input_region": None,
        "input_type": None,
        "input_query": None,
        "resolved_region_id": None,
        "resolved_type_id": None,
        "selected_pokemon_id": None,
        "random_seed": seed if isinstance(seed, str) else (None if seed is None else str(seed)),
        "status": "received",
        "error_message": None,
        "duration_ms": None,
        "client_id": client_id,
        "created_at": created_at,
        "updated_at": created_at,
    }
    tool_requests.append(req_row)
    _save("tool_requests.json", tool_requests)

    def _finish_success(selected_pokemon_id):
        trs = _load("tool_requests.json")
        dur = max(0, int(round((time.time() - t0) * 1000)))
        for r in trs:
            if r.get("tool_request_id") == req_row["tool_request_id"]:
                r["status"] = "succeeded"
                r["error_message"] = None
                r["duration_ms"] = dur
                r["selected_pokemon_id"] = selected_pokemon_id
                r["updated_at"] = _now_iso()
                break
        _save("tool_requests.json", trs)

    def _finish_failed(code, message):
        trs = _load("tool_requests.json")
        dur = max(0, int(round((time.time() - t0) * 1000)))
        for r in trs:
            if r.get("tool_request_id") == req_row["tool_request_id"]:
                r["status"] = "failed"
                r["error_message"] = message
                r["duration_ms"] = dur
                r["updated_at"] = _now_iso()
                break
        _save("tool_requests.json", trs)
        return _err(code, message)

    # Validate inputs
    if seed is not None and not isinstance(seed, str):
        return _finish_failed("VALIDATION_ERROR", "seed must be a string.")

    # Enforce limits based on stored requests (include this very call already appended)
    tool_requests = _load("tool_requests.json")
    if _count_in_window(tool_requests, burst_window_s) > burst_n:
        return _finish_failed("RATE_LIMIT", f"Rate limit exceeded for client_id={client_id} (burst {burst_n}/{burst_window_s}s).")
    if _count_today(tool_requests) > daily_quota:
        return _finish_failed("QUOTA_EXCEEDED", f"Daily quota exceeded for client_id={client_id}.")

    pokemon = _load("pokemon.json")
    active = [p for p in pokemon if isinstance(p, dict) and p.get("status") == "active"]

    if not active:
        return _finish_failed("NOT_FOUND", "No selectable Pokémon in catalog.")

    rng = random.Random(seed) if seed is not None else random.Random()
    chosen = rng.choice(active)

    chosen_id = chosen.get("pokemon_id")
    if not chosen_id:
        # Datastore inconsistency; treat as failed request
        return _finish_failed("NOT_FOUND", "Selected Pokémon record is missing pokemon_id.")

    _finish_success(chosen_id)

    return {
        "pokemon": chosen,
        "meta": {
            "tool_request_id": req_row["tool_request_id"],
            "seed": seed,
        },
    }

def random_pokemon_from_region(region, **_extra):
    import json, os, datetime, time, random, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0021000" if __import__("os").path.isdir("./environment_mix/0021000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    tool_name = "random-pokemon-from-region"
    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        if not isinstance(s, str):
            return None
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}_{secrets.token_hex(8)}"

    def _norm_slug(s):
        s = s.strip().lower()
        s = re.sub(r"[\s_]+", "-", s)
        s = re.sub(r"[^a-z0-9-]", "", s)
        s = re.sub(r"-{2,}", "-", s).strip("-")
        return s

    def _finalize_and_save(tool_requests_rows, req_row, status, error_message=None, selected_pokemon_id=None, resolved_region_id=None, duration_ms=None):
        now = _now_iso()
        req_row["status"] = status
        req_row["updated_at"] = now
        if status == "failed":
            req_row["error_message"] = error_message if error_message is not None else "Request failed."
            req_row["selected_pokemon_id"] = None
        else:
            req_row["error_message"] = None
            req_row["selected_pokemon_id"] = selected_pokemon_id
        if resolved_region_id is not None:
            req_row["resolved_region_id"] = resolved_region_id
        if duration_ms is not None:
            req_row["duration_ms"] = duration_ms
        _save("tool_requests.json", tool_requests_rows)
        return req_row

    def _enforce_limits_and_log_received(tool_requests_rows, req_row, client_id):
        burst_n = 30
        burst_window_s = 10
        daily_quota = 5000

        now_dt = datetime.datetime.utcnow()
        window_start = now_dt - datetime.timedelta(seconds=burst_window_s)
        day_start = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)

        burst_count = 0
        daily_count = 0

        for r in tool_requests_rows:
            if not isinstance(r, dict):
                continue
            if r.get("client_id") != client_id:
                continue
            ca = _parse_iso(r.get("created_at"))
            if ca is None:
                continue
            if ca >= window_start:
                burst_count += 1
            if ca >= day_start:
                daily_count += 1

        tool_requests_rows.append(req_row)
        _save("tool_requests.json", tool_requests_rows)

        if burst_count >= burst_n:
            return _err("RATE_LIMIT", f"Rate limit exceeded for client_id={client_id} (burst {burst_n}/{burst_window_s}s).")
        if daily_count >= daily_quota:
            return _err("QUOTA_EXCEEDED", f"Daily quota exceeded for client_id={client_id} ({daily_quota}/day).")
        return None

    # Ambient auth: tool available if datastore has at least one active region and one active pokemon.
    regions_rows = _load("regions.json")
    pokemon_rows = _load("pokemon.json")
    if not any(isinstance(r, dict) and r.get("status") == "active" for r in regions_rows) or not any(isinstance(p, dict) and p.get("status") == "active" for p in pokemon_rows):
        return _err("UNAUTHORIZED", "Tool is not available because no active regions and active Pokémon are configured.")

    client_id = _extra.get("client_id") or "web:chat"
    tool_requests_rows = _load("tool_requests.json")

    created_at = _now_iso()
    req_row = {
        "tool_request_id": _new_id("trq"),
        "tool_name": tool_name,
        "input_region": region if isinstance(region, str) else (None if region is None else str(region)),
        "input_type": None,
        "input_query": None,
        "resolved_region_id": None,
        "resolved_type_id": None,
        "selected_pokemon_id": None,
        "random_seed": None,
        "status": "received",
        "error_message": None,
        "duration_ms": None,
        "client_id": client_id,
        "created_at": created_at,
        "updated_at": created_at,
    }

    limit_err = _enforce_limits_and_log_received(tool_requests_rows, req_row, client_id)
    if limit_err:
        duration_ms = int((time.time() - t0) * 1000)
        # tool_requests row already saved in 'received'; transition to failed
        tool_requests_rows = _load("tool_requests.json")
        for r in tool_requests_rows[::-1]:
            if isinstance(r, dict) and r.get("tool_request_id") == req_row["tool_request_id"]:
                req_row = r
                break
        _finalize_and_save(tool_requests_rows, req_row, "failed", error_message=limit_err["error"]["message"], duration_ms=duration_ms)
        return limit_err

    # Validate input
    if not isinstance(region, str) or not region.strip():
        duration_ms = int((time.time() - t0) * 1000)
        tool_requests_rows = _load("tool_requests.json")
        for r in tool_requests_rows[::-1]:
            if isinstance(r, dict) and r.get("tool_request_id") == req_row["tool_request_id"]:
                req_row = r
                break
        _finalize_and_save(tool_requests_rows, req_row, "failed", error_message="Business rule: region is required and must be a non-empty string.", duration_ms=duration_ms)
        return _err("VALIDATION_ERROR", "Business rule: region is required and must be a non-empty string.", field="region")

    region_in = region.strip()

    # Resolve region strictly by slug (case-insensitive), BUT accept region_id as well (audit defect fix).
    norm = _norm_slug(region_in)
    resolved_region = None
    for r in regions_rows:
        if not isinstance(r, dict):
            continue
        if r.get("status") != "active":
            continue
        slug = r.get("slug")
        if isinstance(slug, str) and _norm_slug(slug) == norm:
            resolved_region = r
            break
    if resolved_region is None:
        # fallback: treat input as region_id
        for r in regions_rows:
            if not isinstance(r, dict):
                continue
            if r.get("status") != "active":
                continue
            if r.get("region_id") == region_in:
                resolved_region = r
                break

    if resolved_region is None:
        duration_ms = int((time.time() - t0) * 1000)
        tool_requests_rows = _load("tool_requests.json")
        for r in tool_requests_rows[::-1]:
            if isinstance(r, dict) and r.get("tool_request_id") == req_row["tool_request_id"]:
                req_row = r
                break
        msg = f"Business rule: random-pokemon-from-region must resolve the provided region to an active regions.slug (or a region_id). Unknown region '{region_in}'."
        _finalize_and_save(tool_requests_rows, req_row, "failed", error_message=msg, duration_ms=duration_ms)
        return _err("VALIDATION_ERROR", msg, field="region")

    dex_start = resolved_region.get("dex_start")
    dex_end = resolved_region.get("dex_end")
    if not isinstance(dex_start, int) or not isinstance(dex_end, int) or dex_start < 1 or dex_end < dex_start:
        duration_ms = int((time.time() - t0) * 1000)
        tool_requests_rows = _load("tool_requests.json")
        for r in tool_requests_rows[::-1]:
            if isinstance(r, dict) and r.get("tool_request_id") == req_row["tool_request_id"]:
                req_row = r
                break
        msg = "Region configuration invalid (dex_start/dex_end)."
        _finalize_and_save(tool_requests_rows, req_row, "failed", error_message=msg, duration_ms=duration_ms, resolved_region_id=resolved_region.get("region_id"))
        return _err("CONFLICT", msg)

    # Select eligible Pokémon
    eligible = []
    for p in pokemon_rows:
        if not isinstance(p, dict):
            continue
        if p.get("status") != "active":
            continue
        ndn = p.get("national_dex_number")
        if not isinstance(ndn, int):
            continue
        if dex_start <= ndn <= dex_end:
            eligible.append(p)

    if not eligible:
        duration_ms = int((time.time() - t0) * 1000)
        tool_requests_rows = _load("tool_requests.json")
        for r in tool_requests_rows[::-1]:
            if isinstance(r, dict) and r.get("tool_request_id") == req_row["tool_request_id"]:
                req_row = r
                break
        msg = f"Region '{resolved_region.get('slug')}' exists but has no selectable active Pokémon in national dex range {dex_start}-{dex_end}."
        _finalize_and_save(tool_requests_rows, req_row, "failed", error_message=msg, duration_ms=duration_ms, resolved_region_id=resolved_region.get("region_id"))
        return _err("NOT_FOUND", msg)

    # Random selection; optional deterministic seed accepted via runtime context for debugging
    seed = _extra.get("random_seed")
    rng = random.Random()
    if isinstance(seed, str) and seed:
        rng.seed(seed)
    else:
        seed = None  # only store if provided

    chosen = rng.choice(eligible)
    chosen_id = chosen.get("pokemon_id")
    if not chosen_id:
        duration_ms = int((time.time() - t0) * 1000)
        tool_requests_rows = _load("tool_requests.json")
        for r in tool_requests_rows[::-1]:
            if isinstance(r, dict) and r.get("tool_request_id") == req_row["tool_request_id"]:
                req_row = r
                break
        msg = "Selected Pokémon record is missing pokemon_id."
        _finalize_and_save(tool_requests_rows, req_row, "failed", error_message=msg, duration_ms=duration_ms, resolved_region_id=resolved_region.get("region_id"))
        return _err("CONFLICT", msg)

    duration_ms = int((time.time() - t0) * 1000)
    tool_requests_rows = _load("tool_requests.json")
    for r in tool_requests_rows[::-1]:
        if isinstance(r, dict) and r.get("tool_request_id") == req_row["tool_request_id"]:
            req_row = r
            break
    req_row["random_seed"] = seed
    _finalize_and_save(tool_requests_rows, req_row, "succeeded", selected_pokemon_id=chosen_id, resolved_region_id=resolved_region.get("region_id"), duration_ms=duration_ms)

    # Return the Pokémon row (not fabricated)
    return {"pokemon": chosen, "region": resolved_region, "meta": {"duration_ms": duration_ms}}

def random_pokemon_by_type(type=None, **_extra):
    import json, os, datetime, time, random, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0021000" if __import__("os").path.isdir("./environment_mix/0021000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
