    tool_requests_rows = _load("tool_requests.json")

    created_at = _now_iso()
    req_row = {
        "tool_request_id": _new_id("trq"),
        "tool_name": tool_name,
        "input_region": None,
        "input_type": type if isinstance(type, str) else (None if type is None else str(type)),
        "input_query": None,
        "resolved_region_id": None,
        "resolved_type_id": None,
        "selected_pokemon_id": None,
        "random_seed": None,
        "status": "received",
        "error_message": None,
        "duration_ms": None,
        "client_id": client_id,
        "created_at": created_at,
        "updated_at": created_at,
    }

    limit_err = _enforce_limits_and_log_received(tool_requests_rows, req_row, client_id)
    if limit_err:
        duration_ms = int((time.time() - t0) * 1000)
        tool_requests_rows = _load("tool_requests.json")
        for r in tool_requests_rows[::-1]:
            if isinstance(r, dict) and r.get("tool_request_id") == req_row["tool_request_id"]:
                req_row = r
                break
        _finalize_and_save(tool_requests_rows, req_row, "failed", error_message=limit_err["error"]["message"], duration_ms=duration_ms)
        return limit_err

    # Validate input
    if not isinstance(type, str) or not type.strip():
        duration_ms = int((time.time() - t0) * 1000)
        tool_requests_rows = _load("tool_requests.json")
        for r in tool_requests_rows[::-1]:
            if isinstance(r, dict) and r.get("tool_request_id") == req_row["tool_request_id"]:
                req_row = r
                break
        msg = "Business rule: type is required and must be a non-empty string."
        _finalize_and_save(tool_requests_rows, req_row, "failed", error_message=msg, duration_ms=duration_ms)
        return _err("VALIDATION_ERROR", msg, field="type")

    type_in = type.strip()

    # Resolve type strictly by slug (case-insensitive), BUT accept type_id as well (audit defect fix).
    norm = _norm_slug(type_in)
    resolved_type = None
    for t in types_rows:
        if not isinstance(t, dict):
            continue
        if t.get("status") != "active":
            continue
        slug = t.get("slug")
        if isinstance(slug, str) and _norm_slug(slug) == norm:
            resolved_type = t
            break
    if resolved_type is None:
        for t in types_rows:
            if not isinstance(t, dict):
                continue
            if t.get("status") != "active":
                continue
            if t.get("type_id") == type_in:
                resolved_type = t
                break

    if resolved_type is None:
        duration_ms = int((time.time() - t0) * 1000)
        tool_requests_rows = _load("tool_requests.json")
        for r in tool_requests_rows[::-1]:
            if isinstance(r, dict) and r.get("tool_request_id") == req_row["tool_request_id"]:
                req_row = r
                break
        msg = f"Business rule: random-pokemon-by-type must resolve the provided type to an active types.slug (or a type_id). Unknown type '{type_in}'."
        _finalize_and_save(tool_requests_rows, req_row, "failed", error_message=msg, duration_ms=duration_ms)
        return _err("VALIDATION_ERROR", msg, field="type")

    type_id = resolved_type.get("type_id")
    if not type_id:
        duration_ms = int((time.time() - t0) * 1000)
        tool_requests_rows = _load("tool_requests.json")
        for r in tool_requests_rows[::-1]:
            if isinstance(r, dict) and r.get("tool_request_id") == req_row["tool_request_id"]:
                req_row = r
                break
        msg = "Type record is missing type_id."
        _finalize_and_save(tool_requests_rows, req_row, "failed", error_message=msg, duration_ms=duration_ms)
        return _err("CONFLICT", msg)

    active_pokemon_by_id = {}
    for p in pokemon_rows:
        if isinstance(p, dict) and p.get("status") == "active" and p.get("pokemon_id"):
            active_pokemon_by_id[p["pokemon_id"]] = p

    eligible_ids = set()
    for pt in pokemon_types_rows:
        if not isinstance(pt, dict):
            continue
        if pt.get("type_id") != type_id:
            continue
        pid = pt.get("pokemon_id")
        if pid in active_pokemon_by_id:
            eligible_ids.add(pid)

    if not eligible_ids:
        duration_ms = int((time.time() - t0) * 1000)
        tool_requests_rows = _load("tool_requests.json")
        for r in tool_requests_rows[::-1]:
            if isinstance(r, dict) and r.get("tool_request_id") == req_row["tool_request_id"]:
                req_row = r
                break
        msg = f"Type '{resolved_type.get('slug')}' exists but has no selectable active Pokémon in the catalog."
        _finalize_and_save(tool_requests_rows, req_row, "failed", error_message=msg, duration_ms=duration_ms, resolved_type_id=type_id)
        return _err("NOT_FOUND", msg)

    seed = _extra.get("random_seed")
    rng = random.Random()
    if isinstance(seed, str) and seed:
        rng.seed(seed)
    else:
        seed = None

    chosen_id = rng.choice(sorted(eligible_ids))
    chosen = active_pokemon_by_id.get(chosen_id)
    if not chosen:
        duration_ms = int((time.time() - t0) * 1000)
        tool_requests_rows = _load("tool_requests.json")
        for r in tool_requests_rows[::-1]:
            if isinstance(r, dict) and r.get("tool_request_id") == req_row["tool_request_id"]:
                req_row = r
                break
        msg = "Selected Pokémon reference could not be resolved."
        _finalize_and_save(tool_requests_rows, req_row, "failed", error_message=msg, duration_ms=duration_ms, resolved_type_id=type_id)
        return _err("CONFLICT", msg)

    duration_ms = int((time.time() - t0) * 1000)
    tool_requests_rows = _load("tool_requests.json")
    for r in tool_requests_rows[::-1]:
        if isinstance(r, dict) and r.get("tool_request_id") == req_row["tool_request_id"]:
            req_row = r
            break
    req_row["random_seed"] = seed
    _finalize_and_save(tool_requests_rows, req_row, "succeeded", selected_pokemon_id=chosen_id, resolved_type_id=type_id, duration_ms=duration_ms)

    return {"pokemon": chosen, "type": resolved_type, "meta": {"duration_ms": duration_ms}}

def pokemon_query(query, **_extra):
    import json, os, datetime, time, random, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0021000" if __import__("os").path.isdir("./environment_mix/0021000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    tool_name = "pokemon-query"
    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        if not isinstance(s, str):
            return None
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}_{secrets.token_hex(8)}"

    def _norm_slug(s):
        s = s.strip().lower()
        s = re.sub(r"[\s_]+", "-", s)
        s = re.sub(r"[^a-z0-9-]", "", s)
        s = re.sub(r"-{2,}", "-", s).strip("-")
        return s

    # Ambient auth availability check: tool exists if there is any catalog
    if not _load("pokemon.json"):
        return _err("UNAUTHORIZED", "Tool is not available in the current workspace context.")

    client_id = _extra.get("client_id") or "web:chat"
    burst_n = 30
    burst_window_s = 10
    daily_quota = 5000

    tool_requests = _load("tool_requests.json")
    created_at = _now_iso()

    # Create request row (must persist raw input_query)
    req_row = {
        "tool_request_id": _new_id("trq"),
        "tool_name": tool_name,
        "input_region": None,
        "input_type": None,
        "input_query": query if isinstance(query, str) else (None if query is None else str(query)),
        "resolved_region_id": None,
        "resolved_type_id": None,
        "selected_pokemon_id": None,
        "random_seed": None,
        "status": "received",
        "error_message": None,
        "duration_ms": None,
        "client_id": client_id,
        "created_at": created_at,
        "updated_at": created_at,
    }
    tool_requests.append(req_row)
    _save("tool_requests.json", tool_requests)

    def _finish_failed(code, message, **extra):
        trs = _load("tool_requests.json")
        dur = max(0, int(round((time.time() - t0) * 1000)))
        for r in trs:
            if r.get("tool_request_id") == req_row["tool_request_id"]:
                r["status"] = "failed"
                r["error_message"] = message
                r["duration_ms"] = dur
                r["updated_at"] = _now_iso()
                break
        _save("tool_requests.json", trs)
        return _err(code, message, **extra)

    def _finish_success(selected_pokemon_id=None, resolved_region_id=None, resolved_type_id=None):
        trs = _load("tool_requests.json")
        dur = max(0, int(round((time.time() - t0) * 1000)))
        for r in trs:
            if r.get("tool_request_id") == req_row["tool_request_id"]:
                r["status"] = "succeeded"
                r["error_message"] = None
                r["duration_ms"] = dur
                r["updated_at"] = _now_iso()
                if resolved_region_id is not None:
                    r["resolved_region_id"] = resolved_region_id
                if resolved_type_id is not None:
                    r["resolved_type_id"] = resolved_type_id
                if selected_pokemon_id is not None:
                    r["selected_pokemon_id"] = selected_pokemon_id
                break
        _save("tool_requests.json", trs)

    # Validate
    if not isinstance(query, str):
        return _finish_failed("VALIDATION_ERROR", "query must be a string.", field="query")
    if not query.strip():
        return _finish_failed("VALIDATION_ERROR", "query is required.", field="query")

    # Enforce limits
    tool_requests = _load("tool_requests.json")

    def _count_in_window(rows, window_s):
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)
        c = 0
        for r in rows:
            if r.get("tool_name") != tool_name:
                continue
            if (r.get("client_id") or "web:chat") != client_id:
                continue
            dt = _parse_iso(r.get("created_at"))
            if dt and dt >= cutoff:
                c += 1
        return c

    def _count_today(rows):
        today = datetime.datetime.utcnow().date()
        c = 0
        for r in rows:
            if r.get("tool_name") != tool_name:
                continue
            if (r.get("client_id") or "web:chat") != client_id:
                continue
            dt = _parse_iso(r.get("created_at"))
            if dt and dt.date() == today:
                c += 1
        return c

    if _count_in_window(tool_requests, burst_window_s) > burst_n:
        return _finish_failed("RATE_LIMIT", f"Rate limit exceeded for client_id={client_id} (burst {burst_n}/{burst_window_s}s).")
    if _count_today(tool_requests) > daily_quota:
        return _finish_failed("QUOTA_EXCEEDED", f"Daily quota exceeded for client_id={client_id}.")

    q = query.strip().lower()

    regions = _load("regions.json")
    types = _load("types.json")
    pokemon = _load("pokemon.json")
    pokemon_types = _load("pokemon_types.json")

    # Very light intent extraction (allowed by rules); strict resolution only.
    resolved_region = None
    resolved_type = None

    # Attempt to extract region by matching any known region slug or display_name token
    for r in regions:
        if not isinstance(r, dict) or r.get("status") != "active":
            continue
        slug = r.get("slug")
        disp = (r.get("display_name") or "").strip().lower()
        if isinstance(slug, str) and slug and re.search(r"\b" + re.escape(slug) + r"\b", q):
            resolved_region = r
            break
        if disp and re.search(r"\b" + re.escape(disp) + r"\b", q):
            resolved_region = r
            break

    # Attempt to extract type by matching known type slugs (word boundary)
    for t in types:
        if not isinstance(t, dict) or t.get("status") != "active":
            continue
        slug = t.get("slug")
        if isinstance(slug, str) and slug and re.search(r"\b" + re.escape(slug) + r"\b", q):
            resolved_type = t
            break

    # Build candidate set
    active_pokemon = [p for p in pokemon if isinstance(p, dict) and p.get("status") == "active" and p.get("pokemon_id")]
    if not active_pokemon:
        return _finish_failed("NOT_FOUND", "No selectable Pokémon in catalog.")

    candidates = active_pokemon

    if resolved_region is not None:
        dex_start = resolved_region.get("dex_start")
        dex_end = resolved_region.get("dex_end")
        if not isinstance(dex_start, int) or not isinstance(dex_end, int):
            resolved_region = None  # do not persist invalid reference
        else:
            candidates = [p for p in candidates if isinstance(p.get("national_dex_number"), int) and dex_start <= p["national_dex_number"] <= dex_end]

    if resolved_type is not None:
        type_id = resolved_type.get("type_id")
        if not isinstance(type_id, str) or not type_id:
            resolved_type = None
        else:
            pids_for_type = set()
            for pt in pokemon_types:
                if isinstance(pt, dict) and pt.get("type_id") == type_id and isinstance(pt.get("pokemon_id"), str):
                    pids_for_type.add(pt["pokemon_id"])
            candidates = [p for p in candidates if p.get("pokemon_id") in pids_for_type]

    if not candidates:
        # Well-formed but yields no matches (spec says NOT_FOUND for well-formed query)
        # Persist any resolved references (strictly existing rows only).
        _finish_failed("NOT_FOUND", "No Pokémon matched the query.")
        return _err("NOT_FOUND", "No Pokémon matched the query.")

    chosen = random.choice(candidates)
    chosen_id = chosen.get("pokemon_id")

    resolved_region_id = resolved_region.get("region_id") if resolved_region else None
    resolved_type_id = resolved_type.get("type_id") if resolved_type else None

    _finish_success(selected_pokemon_id=chosen_id, resolved_region_id=resolved_region_id, resolved_type_id=resolved_type_id)

    return {
        "pokemon": chosen,
        "inferred": {
            "region": resolved_region,
            "type": resolved_type,
        },
        "meta": {
            "tool_request_id": req_row["tool_request_id"],
        },
    }

def list_pokemon(status=None, region_id=None, is_legendary=None, is_mythical=None, q=None, national_dex_min=None, national_dex_max=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0021000" if __import__("os").path.isdir("./environment_mix/0021000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    tool_requests = _load("tool_requests.json")

    def _new_id(prefix):
        import secrets
        return f"{prefix}_{secrets.token_hex(12)}"

    req_row = {
        "tool_request_id": _new_id("tr"),
        "tool_name": "pokemon-query",  # closest available in enum; list-pokemon is not modeled as a tool in schema
        "input_region": None,
        "input_type": None,
        "input_query": None,
        "resolved_region_id": None,
        "resolved_type_id": None,
        "selected_pokemon_id": None,
        "random_seed": None,
        "status": "received",
        "error_message": None,
        "duration_ms": None,
        "client_id": None,
        "created_at": now,
        "updated_at": now,
    }
    tool_requests.append(req_row)
    _save("tool_requests.json", tool_requests)

    def _finish(ok, error_message=None):
        end = time.time()
        duration_ms = int(round((end - t0) * 1000))
        trs = _load("tool_requests.json")
        for r in trs:
            if r.get("tool_request_id") == req_row["tool_request_id"]:
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                r["duration_ms"] = max(0, duration_ms)
                if ok:
                    r["status"] = "succeeded"
                    r["error_message"] = None
                else:
                    r["status"] = "failed"
                    r["error_message"] = error_message or "Request failed"
                break
        _save("tool_requests.json", trs)

    # --- Validation ---
    try:
        if status is not None and status not in ("active", "disabled", "deprecated"):
            _finish(False, "Invalid status")
            return _err("VALIDATION_ERROR", "Invalid 'status'.", field="status")
        if region_id is not None and not isinstance(region_id, str):
            _finish(False, "Invalid region_id")
            return _err("VALIDATION_ERROR", "Invalid 'region_id'.", field="region_id")
        if is_legendary is not None and not isinstance(is_legendary, bool):
            _finish(False, "Invalid is_legendary")
            return _err("VALIDATION_ERROR", "Invalid 'is_legendary'.", field="is_legendary")
        if is_mythical is not None and not isinstance(is_mythical, bool):
            _finish(False, "Invalid is_mythical")
            return _err("VALIDATION_ERROR", "Invalid 'is_mythical'.", field="is_mythical")
        if q is not None and not isinstance(q, str):
            _finish(False, "Invalid q")
            return _err("VALIDATION_ERROR", "Invalid 'q'.", field="q")
        if national_dex_min is not None:
            if not isinstance(national_dex_min, int) or national_dex_min < 1:
                _finish(False, "Invalid national_dex_min")
                return _err("VALIDATION_ERROR", "Invalid 'national_dex_min'.", field="national_dex_min")
        if national_dex_max is not None:
            if not isinstance(national_dex_max, int) or national_dex_max < 1:
                _finish(False, "Invalid national_dex_max")
                return _err("VALIDATION_ERROR", "Invalid 'national_dex_max'.", field="national_dex_max")
        if national_dex_min is not None and national_dex_max is not None and national_dex_max < national_dex_min:
            _finish(False, "national_dex_max < national_dex_min")
            return _err("VALIDATION_ERROR", "'national_dex_max' must be >= 'national_dex_min'.", field="national_dex_max")

        if limit is None:
            limit_v = 50
        else:
            if not isinstance(limit, int) or limit < 1 or limit > 200:
                _finish(False, "Invalid limit")
                return _err("VALIDATION_ERROR", "Invalid 'limit'. Must be 1..200.", field="limit")
            limit_v = limit

        if cursor is not None and not isinstance(cursor, str):
            _finish(False, "Invalid cursor")
            return _err("VALIDATION_ERROR", "Invalid 'cursor'.", field="cursor")

        if sort is None:
            sort_v = "national_dex_number"
        else:
            if sort not in ("national_dex_number", "name", "created_at", "updated_at"):
                _finish(False, "Invalid sort")
                return _err("VALIDATION_ERROR", "Invalid 'sort'.", field="sort")
            sort_v = sort

        if order is None:
            order_v = "asc"
        else:
            if order not in ("asc", "desc"):
                _finish(False, "Invalid order")
                return _err("VALIDATION_ERROR", "Invalid 'order'.", field="order")
            order_v = order

        # region_id reference validation (if provided) must exist
        resolved_region = None
        if region_id is not None:
            regions = _load("regions.json")
            resolved_region = next((r for r in regions if r.get("region_id") == region_id), None)
            if not resolved_region:
                _finish(False, "Region not found")
                return _err("NOT_FOUND", "Region not found.", region_id=region_id)
            req_row["resolved_region_id"] = resolved_region.get("region_id")
            req_row["input_region"] = region_id  # raw value as provided
            # persist resolution update (still "received")
            trs = _load("tool_requests.json")
            for r in trs:
                if r.get("tool_request_id") == req_row["tool_request_id"]:
                    r["input_region"] = req_row["input_region"]
                    r["resolved_region_id"] = req_row["resolved_region_id"]
                    r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                    break
            _save("tool_requests.json", trs)

        # cursor decode
        start = 0
        if cursor:
            try:
                raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"==").decode("utf-8")
                if not raw.startswith("v1:"):
                    _finish(False, "Invalid cursor")
                    return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
                start_s = raw.split(":", 1)[1]
                start = int(start_s)
                if start < 0:
                    raise ValueError()
            except Exception:
                _finish(False, "Invalid cursor")
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

        # --- Authorization (ambient) ---
        # No explicit auth parameters and no auth collections in schema; treat as accessible if datastore exists.
        pokemon = _load("pokemon.json")
        if pokemon is None:
            _finish(False, "Unauthorized")
            return _err("UNAUTHORIZED", "Caller lacks access.")

        # --- Filtering ---
        qq = (q or "").strip().lower()
        def _match(row):
            if status is not None and row.get("status") != status:
                return False
            if region_id is not None and row.get("primary_region_id") != region_id:
                return False
            if is_legendary is not None and row.get("is_legendary") is not is_legendary:
                return False
            if is_mythical is not None and row.get("is_mythical") is not is_mythical:
                return False
            nd = row.get("national_dex_number")
            if national_dex_min is not None and (not isinstance(nd, int) or nd < national_dex_min):
                return False
            if national_dex_max is not None and (not isinstance(nd, int) or nd > national_dex_max):
                return False
            if qq:
                nn = (row.get("name_normalized") or "").lower()
                nm = (row.get("name") or "").lower()
                if qq not in nn and qq not in nm:
                    return False
            return True

        rows = [r for r in pokemon if isinstance(r, dict) and _match(r)]

        # --- Sorting ---
        def _key(r):
            v = r.get(sort_v)
            # normalize None for stable sort
            if v is None:
                return ""
            return v

        reverse = (order_v == "desc")
        try:
            rows.sort(key=_key, reverse=reverse)
        except Exception:
            # if incomparable types exist in datastore, fall back to string key
            rows.sort(key=lambda r: str(r.get(sort_v, "")), reverse=reverse)

        total = len(rows)
        page = rows[start:start + limit_v]
        next_start = start + len(page)
        has_more = next_start < total
        next_cursor = None
        if has_more:
            token = f"v1:{next_start}".encode("utf-8")
            next_cursor = base64.urlsafe_b64encode(token).decode("utf-8").rstrip("=")

        _finish(True, None)
        return {
            "object": "list",
            "data": page,
            "meta": {
                "total": total,
                "limit": limit_v,
                "cursor": cursor,
                "next_cursor": next_cursor,
                "has_more": has_more,
                "sort": sort_v,
                "order": order_v,
            },
        }
    except Exception as e:
        _finish(False, "Internal error")
        return _err("CONFLICT", "Internal error.", detail=str(e))

def get_pokemon(pokemon_id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0021000" if __import__("os").path.isdir("./environment_mix/0021000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    tool_requests = _load("tool_requests.json")
    def _new_req_id():
        return "tr_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + "_" + os.urandom(6).hex()

    req = {
        "tool_request_id": _new_req_id(),
        "tool_name": "pokemon-query",  # closest enum available
        "input_region": None,
        "input_type": None,
        "input_query": None,
        "resolved_region_id": None,
        "resolved_type_id": None,
        "selected_pokemon_id": None,
        "random_seed": None,
        "status": "received",
        "error_message": None,
        "duration_ms": None,
        "client_id": None,
        "created_at": now,
        "updated_at": now,
    }
    tool_requests.append(req)
    _save("tool_requests.json", tool_requests)

    def _finalize(status_val, err_msg=None, selected_id=None):
        nonlocal tool_requests, req
        tool_requests = _load("tool_requests.json")
        for r in tool_requests:
            if r.get("tool_request_id") == req["tool_request_id"]:
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                r["duration_ms"] = max(0, int(round((time.time() - t0) * 1000)))
                r["status"] = status_val
                r["error_message"] = err_msg
                if selected_id is not None:
                    r["selected_pokemon_id"] = selected_id
                break
        _save("tool_requests.json", tool_requests)

    if not isinstance(pokemon_id, str) or not pokemon_id.strip():
        _finalize("failed", "Invalid pokemon_id.")
        return _err("VALIDATION_ERROR", "pokemon_id must be a non-empty string.", field="pokemon_id")

    pokemon = _load("pokemon.json")
    row = None
    for p in pokemon:
        if isinstance(p, dict) and p.get("pokemon_id") == pokemon_id:
            row = p
            break

    if row is None:
        _finalize("failed", "Pokemon not found.")
        return _err("NOT_FOUND", "Pokemon not found.", pokemon_id=pokemon_id)

    _finalize("succeeded", None, selected_id=row.get("pokemon_id"))
    return {"object": "pokemon", "data": row}

def update_pokemon(pokemon_id, name=None, name_normalized=None, national_dex_number=None, is_legendary=None, is_mythical=None, default_sprite_url=None, primary_region_id=None, status=None, source=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0021000" if __import__("os").path.isdir("./environment_mix/0021000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    tool_requests = _load("tool_requests.json")
    def _new_req_id():
        return "tr_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + "_" + os.urandom(6).hex()

    req = {
        "tool_request_id": _new_req_id(),
        "tool_name": "pokemon-query",  # closest enum available
        "input_region": None,
        "input_type": None,
        "input_query": None,
        "resolved_region_id": None,
        "resolved_type_id": None,
        "selected_pokemon_id": None,
        "random_seed": None,
        "status": "received",
        "error_message": None,
        "duration_ms": None,
        "client_id": None,
        "created_at": now,
        "updated_at": now,
    }
    tool_requests.append(req)
    _save("tool_requests.json", tool_requests)

    def _finalize(status_val, err_msg=None, selected_id=None):
        nonlocal tool_requests, req
        tool_requests = _load("tool_requests.json")
        for r in tool_requests:
            if r.get("tool_request_id") == req["tool_request_id"]:
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                r["duration_ms"] = max(0, int(round((time.time() - t0) * 1000)))
                r["status"] = status_val
                r["error_message"] = err_msg
                if selected_id is not None:
                    r["selected_pokemon_id"] = selected_id
                break
        _save("tool_requests.json", tool_requests)

    # Validate required id
    if not isinstance(pokemon_id, str) or not pokemon_id.strip():
        _finalize("failed", "Invalid pokemon_id.")
        return _err("VALIDATION_ERROR", "pokemon_id must be a non-empty string.", field="pokemon_id")

    # Validate optional fields/types
    if name is not None and (not isinstance(name, str) or name == ""):
        _finalize("failed", "Invalid name.")
        return _err("VALIDATION_ERROR", "name must be a non-empty string.", field="name")
    if name_normalized is not None and (not isinstance(name_normalized, str) or name_normalized == ""):
        _finalize("failed", "Invalid name_normalized.")
        return _err("VALIDATION_ERROR", "name_normalized must be a non-empty string.", field="name_normalized")
    if national_dex_number is not None and (not isinstance(national_dex_number, int) or national_dex_number < 1):
        _finalize("failed", "Invalid national_dex_number.")
        return _err("VALIDATION_ERROR", "national_dex_number must be an integer >= 1.", field="national_dex_number")
    if is_legendary is not None and not isinstance(is_legendary, bool):
        _finalize("failed", "Invalid is_legendary.")
        return _err("VALIDATION_ERROR", "is_legendary must be boolean.", field="is_legendary")
    if is_mythical is not None and not isinstance(is_mythical, bool):
        _finalize("failed", "Invalid is_mythical.")
        return _err("VALIDATION_ERROR", "is_mythical must be boolean.", field="is_mythical")
    if default_sprite_url is not None and not isinstance(default_sprite_url, str):
        _finalize("failed", "Invalid default_sprite_url.")
        return _err("VALIDATION_ERROR", "default_sprite_url must be a string.", field="default_sprite_url")
    if primary_region_id is not None and not isinstance(primary_region_id, str):
        _finalize("failed", "Invalid primary_region_id.")
        return _err("VALIDATION_ERROR", "primary_region_id must be a string.", field="primary_region_id")
    if status is not None and (not isinstance(status, str) or status not in ("active", "disabled", "deprecated")):
        _finalize("failed", "Invalid status.")
        return _err("VALIDATION_ERROR", "Invalid status.", field="status")
    # Tool spec says source enum internal/imported; schema says pokeapi/manual. Enforce tool spec for update endpoint.
    if source is not None and (not isinstance(source, str) or source not in ("internal", "imported")):
        _finalize("failed", "Invalid source.")
        return _err("VALIDATION_ERROR", "Invalid source.", field="source")

    # Authorization: no auth collections exist; treat as permitted.
    pokemon = _load("pokemon.json")
    regions = _load("regions.json")

    idx = None
    for i, p in enumerate(pokemon):
        if isinstance(p, dict) and p.get("pokemon_id") == pokemon_id:
            idx = i
            break
    if idx is None:
        _finalize("failed", "Pokemon not found.")
        return _err("NOT_FOUND", "Pokemon not found.", pokemon_id=pokemon_id)

    current = pokemon[idx]
    cur_status = current.get("status")

    # Foreign key validation for primary_region_id (can be null)
    if primary_region_id is not None:
        if not any(r.get("region_id") == primary_region_id for r in regions):
            _finalize("failed", "primary_region_id missing reference.")
            return _err("VALIDATION_ERROR", "primary_region_id must reference an existing region.", field="primary_region_id")

    # Lifecycle transition validation
    if status is not None:
        allowed = {
            "active": ("disabled", "deprecated"),
            "disabled": ("active", "deprecated"),
            "deprecated": (),
        }
        if cur_status not in allowed:
            _finalize("failed", "Unknown current status.")
            return _err("VALIDATION_ERROR", "Current record has invalid status.", field="status")
        if status != cur_status and status not in allowed[cur_status]:
            _finalize("failed", "Invalid lifecycle transition.")
            return _err("INVALID_TRANSITION", f"Cannot transition status from {cur_status} to {status}.", from_status=cur_status, to_status=status)

    # Uniqueness constraints & required constraints (name <> '')
    # Prepare candidate updated record
    updated = dict(current)
    changed = False

    def _set(field, val):
        nonlocal changed
        if val is None:
            return
        if updated.get(field) != val:
            updated[field] = val
            changed = True

    _set("name", name)
    _set("name_normalized", name_normalized)
    _set("national_dex_number", national_dex_number)
    _set("is_legendary", is_legendary)
    _set("is_mythical", is_mythical)
    _set("default_sprite_url", default_sprite_url)
    _set("primary_region_id", primary_region_id)
    _set("status", status)

    # Map tool-spec source to schema source if possible
    if source is not None:
        mapped = "manual" if source == "internal" else "pokeapi"
        _set("source", mapped)

    # If no changes, treat as idempotent success but must still have effect? This is an update endpoint;
    # real services often succeed idempotently. We'll still refresh updated_at to reflect write intent.
    # However "NO SUCCESS WITHOUT EFFECT" requires a mutation to change something. We'll only succeed if
    # there is at least one actual change OR we can legitimately update updated_at.
    # We'll count updated_at refresh as an effect only if caller supplied at least one updatable field.
    caller_provided_any = any(v is not None for v in (
        name, name_normalized, national_dex_number, is_legendary, is_mythical,
        default_sprite_url, primary_region_id, status, source
    ))
    if not caller_provided_any:
        _finalize("failed", "No fields provided to update.")
        return _err("VALIDATION_ERROR", "At least one field must be provided to update.", field="pokemon_id")

    # Validate constraints on updated
    if not isinstance(updated.get("national_dex_number"), int) or updated["national_dex_number"] < 1:
        _finalize("failed", "national_dex_number constraint.")
        return _err("VALIDATION_ERROR", "national_dex_number must be >= 1.", field="national_dex_number")
    if not isinstance(updated.get("name"), str) or updated["name"] == "":
        _finalize("failed", "name constraint.")
        return _err("VALIDATION_ERROR", "name must be non-empty.", field="name")
    if updated.get("status") not in ("active", "disabled", "deprecated"):
        _finalize("failed", "status constraint.")
        return _err("VALIDATION_ERROR", "status is invalid.", field="status")

    # Enforce uniqueness among other pokemon rows
    for p in pokemon:
        if not isinstance(p, dict) or p.get("pokemon_id") == pokemon_id:
            continue
        if p.get("national_dex_number") == updated.get("national_dex_number"):
            _finalize("failed", "Duplicate national_dex_number.")
            return _err("CONFLICT", "national_dex_number must be unique.", field="national_dex_number")
        if p.get("name_normalized") == updated.get("name_normalized"):
            _finalize("failed", "Duplicate name_normalized.")
            return _err("CONFLICT", "name_normalized must be unique.", field="name_normalized")

    # Apply update
    updated["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    pokemon[idx] = updated
    _save("pokemon.json", pokemon)

    _finalize("succeeded", None, selected_id=updated.get("pokemon_id"))
    return {"object": "pokemon", "data": updated}

def list_regions(status=None, generation=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0021000" if __import__("os").path.isdir("./environment_mix/0021000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    tool_requests = _load("tool_requests.json")
    def _new_req_id():
        return "tr_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + "_" + os.urandom(6).hex()

    req = {
        "tool_request_id": _new_req_id(),
        "tool_name": "pokemon-query",  # closest enum available
        "input_region": None,
        "input_type": None,
        "input_query": None,
        "resolved_region_id": None,
        "resolved_type_id": None,
        "selected_pokemon_id": None,
        "random_seed": None,
        "status": "received",
        "error_message": None,
        "duration_ms": None,
        "client_id": None,
        "created_at": now,
        "updated_at": now,
    }
    tool_requests.append(req)
    _save("tool_requests.json", tool_requests)

    def _finalize(status_val, err_msg=None):
        nonlocal tool_requests, req
        tool_requests = _load("tool_requests.json")
        for r in tool_requests:
            if r.get("tool_request_id") == req["tool_request_id"]:
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                r["duration_ms"] = max(0, int(round((time.time() - t0) * 1000)))
                r["status"] = status_val
                r["error_message"] = err_msg
                break
        _save("tool_requests.json", tool_requests)

    # Validate inputs
    if status is not None and (not isinstance(status, str) or status not in ("active", "disabled")):
        _finalize("failed", "Invalid status filter.")
        return _err("VALIDATION_ERROR", "Invalid status.", field="status")
    if generation is not None:
        if not isinstance(generation, int) or generation < 1 or generation > 20:
            _finalize("failed", "Invalid generation filter.")
            return _err("VALIDATION_ERROR", "Invalid generation.", field="generation")
    if limit is None:
        limit_val = 50
    else:
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            _finalize("failed", "Invalid limit.")
            return _err("VALIDATION_ERROR", "Invalid limit.", field="limit")
        limit_val = limit
    if cursor is not None and not isinstance(cursor, str):
        _finalize("failed", "Invalid cursor.")
        return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
    if sort is None:
        sort_val = "generation"
    else:
        if not isinstance(sort, str) or sort not in ("generation", "slug", "created_at", "updated_at"):
            _finalize("failed", "Invalid sort.")
            return _err("VALIDATION_ERROR", "Invalid sort.", field="sort")
        sort_val = sort
    if order is None:
        order_val = "asc"
    else:
        if not isinstance(order, str) or order not in ("asc", "desc"):
            _finalize("failed", "Invalid order.")
            return _err("VALIDATION_ERROR", "Invalid order.", field="order")
        order_val = order

    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or not isinstance(obj.get("offset"), int) or obj["offset"] < 0:
                _finalize("failed", "Invalid cursor payload.")
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            offset = obj["offset"]
        except (ValueError, json.JSONDecodeError, base64.binascii.Error):
            _finalize("failed", "Invalid cursor decoding.")
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    regions = _load("regions.json")

    def _matches(r):
        if not isinstance(r, dict):
            return False
        if status is not None and r.get("status") != status:
            return False
        if generation is not None and r.get("generation") != generation:
            return False
        return True

    rows = [r for r in regions if _matches(r)]
    reverse = (order_val == "desc")

    def _sort_key(r):
        return (r.get(sort_val), r.get("region_id"))

    try:
        rows.sort(key=_sort_key, reverse=reverse)
    except TypeError:
        rows.sort(key=lambda r: (str(r.get(sort_val)), str(r.get("region_id"))), reverse=reverse)

    total = len(rows)
    page = rows[offset: offset + limit_val]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"offset": next_offset}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    _finalize("succeeded", None)
    return {
        "object": "list",
        "data": page,
        "total": total,
        "limit": limit_val,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }

def list_types(status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, secrets, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0021000" if __import__("os").path.isdir("./environment_mix/0021000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    tool_name_for_log = "pokemon-query"  # tool_requests.enum does not include list-types; log under existing tool
    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        if not isinstance(s, str):
            return None
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}_{secrets.token_hex(8)}"

    # Ambient auth: if datastore has types collection, allow. Only unauthorized if cannot possibly serve.
    if not _load("types.json"):
        return _err("UNAUTHORIZED", "Tool is not available in the current workspace context.")

    client_id = _extra.get("client_id") or "web:chat"
    burst_n = 30
    burst_window_s = 10
    daily_quota = 20000

    # Log request first (observable dynamics)
    tool_requests = _load("tool_requests.json")
    created_at = _now_iso()
    req_row = {
        "tool_request_id": _new_id("trq"),
        "tool_name": tool_name_for_log,
        "input_region": None,
        "input_type": None,
        "input_query": None,
        "resolved_region_id": None,
        "resolved_type_id": None,
        "selected_pokemon_id": None,
        "random_seed": None,
        "status": "received",
        "error_message": None,
        "duration_ms": None,
        "client_id": client_id,
        "created_at": created_at,
        "updated_at": created_at,
    }
    tool_requests.append(req_row)
    _save("tool_requests.json", tool_requests)

    def _finish(ok, error_message=None):
        trs = _load("tool_requests.json")
        dur = max(0, int(round((time.time() - t0) * 1000)))
        for r in trs:
            if r.get("tool_request_id") == req_row["tool_request_id"]:
                r["duration_ms"] = dur
                r["updated_at"] = _now_iso()
                if ok:
                    r["status"] = "succeeded"
                    r["error_message"] = None
                else:
                    r["status"] = "failed"
                    r["error_message"] = error_message or "Request failed"
                break
        _save("tool_requests.json", trs)

    # Enforce limits
    tool_requests = _load("tool_requests.json")

    def _count_in_window(rows, window_s):
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)
        c = 0
        for r in rows:
            if (r.get("client_id") or "web:chat") != client_id:
                continue
            dt = _parse_iso(r.get("created_at"))
            if dt and dt >= cutoff:
                c += 1
        return c

    def _count_today(rows):
        today = datetime.datetime.utcnow().date()
        c = 0
        for r in rows:
            if (r.get("client_id") or "web:chat") != client_id:
                continue
            dt = _parse_iso(r.get("created_at"))
            if dt and dt.date() == today:
                c += 1
        return c

    if _count_in_window(tool_requests, burst_window_s) > burst_n:
        _finish(False, f"Rate limit exceeded for client_id={client_id} (burst {burst_n}/{burst_window_s}s).")
        return _err("RATE_LIMIT", f"Rate limit exceeded for client_id={client_id} (burst {burst_n}/{burst_window_s}s).")
    if _count_today(tool_requests) > daily_quota:
        _finish(False, f"Daily quota exceeded for client_id={client_id}.")
        return _err("QUOTA_EXCEEDED", f"Daily quota exceeded for client_id={client_id}.")

    # Validation
    if status is not None and status not in ("active", "disabled"):
        _finish(False, "Invalid 'status'.")
        return _err("VALIDATION_ERROR", "Invalid 'status'.", field="status")

    if limit is None:
        limit_v = 50
    else:
        if not isinstance(limit, int):
            _finish(False, "Invalid 'limit'.")
            return _err("VALIDATION_ERROR", "Invalid 'limit'.", field="limit")
        if limit < 1 or limit > 200:
            _finish(False, "Invalid 'limit'.")
            return _err("VALIDATION_ERROR", "Invalid 'limit'.", field="limit")
        limit_v = limit

    if sort is None:
        sort_v = "slug"
    else:
        if sort not in ("slug", "created_at", "updated_at"):
            _finish(False, "Invalid 'sort'.")
            return _err("VALIDATION_ERROR", "Invalid 'sort'.", field="sort")
        sort_v = sort

    if order is None:
        order_v = "asc"
    else:
        if order not in ("asc", "desc"):
            _finish(False, "Invalid 'order'.")
            return _err("VALIDATION_ERROR", "Invalid 'order'.", field="order")
        order_v = order

    def _encode_cursor(key):
        raw = json.dumps({"k": key}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur.strip():
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        c = cur.strip()
        # Accept either opaque base64 cursor (preferred) OR a plain id/slug passed by callers (relax strictness).
        # If base64 decode fails, treat as plain key.
        try:
            pad = "=" * (-len(c) % 4)
            data = base64.urlsafe_b64decode((c + pad).encode("ascii"))
            obj = json.loads(data.decode("utf-8"))
            key = obj.get("k")
            if not isinstance(key, str) or not key:
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
            return key
        except Exception:
            # Plain key fallback
            return c

    after_key = _decode_cursor(cursor)
    if isinstance(after_key, dict) and after_key.get("error"):
        _finish(False, after_key["error"]["message"])
        return after_key

    rows = _load("types.json")
    rows = [r for r in rows if isinstance(r, dict)]

    if status is not None:
        rows = [r for r in rows if r.get("status") == status]

    def _sort_key(r):
        v = r.get(sort_v)
        return "" if v is None else v

    reverse = (order_v == "desc")
    try:
        rows_sorted = sorted(rows, key=_sort_key, reverse=reverse)
    except TypeError:
        # Mixed types; fall back to string sort
        rows_sorted = sorted(rows, key=lambda r: str(_sort_key(r)), reverse=reverse)

    start_idx = 0
    if after_key is not None:
        # Support after_key being either type_id or slug
        found = False
        for i, r in enumerate(rows_sorted):
            if r.get("type_id") == after_key or r.get("slug") == after_key:
                start_idx = i + 1
                found = True
                break
        if not found:
            # Relaxed behavior: unknown cursor returns empty page (not an error), matching "read returns empty set"
            start_idx = len(rows_sorted)

    page = rows_sorted[start_idx:start_idx + limit_v]
    has_more = start_idx + limit_v < len(rows_sorted)
    next_cursor = None
    if has_more and page:
        # Cursor is the last returned row's sort key preference: use type_id to be stable
        last = page[-1]
        next_cursor = _encode_cursor(last.get("type_id") or last.get("slug") or "")

    _finish(True)

    return {
        "types": page,
        "meta": {
            "total": len(rows_sorted),
            "limit": limit_v,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "request_id": req_row["tool_request_id"],
            "sort": sort_v,
            "order": order_v,
        },
    }
